mapper.select:
SELECT t.TEMPLATEID, t.TEMPLATENO, t.TEMPLATENAME, t.TEMPLATETYPE, t.TEMPLATECATEGORY, t.TEMPLATEFORMAT, t.TEMPLATEVERSION, t.TEMPLATESTATUS, t.DESCRIPTION, t.REMARK, t.ORGID, t.CREATETIME, t.CREATEUSER, t.UPDATETIME, t.UPDATEUSER, cu.USER_NAME AS CREATE_USER_NAME, uu.USER_NAME AS UPDATE_USER_NAME, o.ORG_NAME, (SELECT COUNT(*) FROM TBL_FINANCING_REPORT_RECORDS r WHERE r.TEMPLATEID = t.TEMPLATEID) AS USAGE_COUNT, (SELECT MAX(r.CREATETIME) FROM TBL_FINANCING_REPORT_RECORDS r WHERE r.TEMPLATEID = t.TEMPLATEID) AS LAST_USAGE_TIME FROM TBL_FINANCING_REPORT_TEMPLATES t LEFT JOIN SYS_USER cu ON t.CREATEUSER = cu.USER_ID LEFT JOIN SYS_USER uu ON t.UPDATEUSER = uu.USER_ID LEFT JOIN SYS_ORG o ON t.ORGID = o.ORG_ID
AND t.TEMPLATENO LIKE CONCAT('%', #{params.templateNo}, '%')
AND t.TEMPLATENAME LIKE CONCAT('%', #{params.templateName}, '%')
AND t.TEMPLATETYPE = #{params.templateType}
AND t.TEMPLATECATEGORY = #{params.templateCategory}
AND t.TEMPLATESTATUS = #{params.templateStatus}
AND t.ORGID = #{params.orgId}
AND t.CREATETIME >= #{params.createTimeStart}
AND t.CREATETIME <= #{params.createTimeEnd}
ORDER BY t.UPDATETIME DESC

mapper.insert:
INSERT INTO TBL_FINANCING_REPORT_TEMPLATES (
    TEMPLATENO, TEMPLATENAME, TEMPLATETYPE, TEMPLATECATEGORY, TEMPLATEFORMAT,
    TEMPLATECONTENT, TEMPLATEPARAMS, TEMPLATESTYLE, TEMPLATEVERSION, TEMPLATESTATUS,
    DESCRIPTION, REMARK, ORGID, CREATETIME, CREATEUSER, UPDATETIME, UPDATEUSER
) VALUES (
    #{templateNo}, #{templateName}, #{templateType}, #{templateCategory}, #{templateFormat},
    #{templateContent}, #{templateParams}, #{templateStyle}, #{templateVersion}, #{templateStatus},
    #{description}, #{remark}, #{orgId}, CURRENT_TIMESTAMP, #{createUser}, CURRENT_TIMESTAMP, #{updateUser}
)

mapper.select:
SELECT 
    r.RECORDID, r.REPORTNO, r.REPORTNAME, r.TEMPLATEID, r.REPORTTYPE, r.REPORTPERIOD,
    r.STARTDATE, r.ENDDATE, r.REPORTFORMAT, r.REPORTSIZE, r.GENERATETYPE, r.REPORTSTATUS,
    r.GENERATETIME, r.COMPLETETIME, r.DOWNLOADCOUNT, r.LASTDOWNLOADTIME,
    r.DESCRIPTION, r.REMARK, r.ORGID, r.CREATETIME, r.CREATEUSER, r.UPDATETIME, r.UPDATEUSER,
    t.TEMPLATENAME AS TEMPLATE_NAME,
    cu.USER_NAME AS CREATE_USER_NAME,
    uu.USER_NAME AS UPDATE_USER_NAME,
    o.ORG_NAME
FROM TBL_FINANCING_REPORT_RECORDS r
LEFT JOIN TBL_FINANCING_REPORT_TEMPLATES t ON r.TEMPLATEID = t.TEMPLATEID
LEFT JOIN SYS_USER cu ON r.CREATEUSER = cu.USER_ID
LEFT JOIN SYS_USER uu ON r.UPDATEUSER = uu.USER_ID
LEFT JOIN SYS_ORG o ON r.ORGID = o.ORG_ID


        AND r.REPORTNO LIKE CONCAT('%', #{params.reportNo}, '%')


        AND r.REPORTNAME LIKE CONCAT('%', #{params.reportName}, '%')


        AND r.REPORTTYPE = #{params.reportType}


        AND r.REPORTSTATUS = #{params.reportStatus}


        AND r.TEMPLATEID = #{params.templateId}


        AND r.ORGID = #{params.orgId}


        AND r.STARTDATE >= #{params.startDate}


        AND r.ENDDATE <= #{params.endDate}


        AND r.GENERATETIME >= #{params.generateTimeStart}


        AND r.GENERATETIME <= #{params.generateTimeEnd}


ORDER BY r.CREATETIME DESC

mapper.insert:
INSERT INTO TBL_FINANCING_REPORT_RECORDS (
    REPORTNO, REPORTNAME, TEMPLATEID, REPORTTYPE, REPORTPERIOD, STARTDATE, ENDDATE,
    REPORTFORMAT, REPORTPARAMS, GENERATETYPE, REPORTSTATUS, GENERATETIME,
    DESCRIPTION, REMARK, ORGID, CREATETIME, CREATEUSER, UPDATETIME, UPDATEUSER
) VALUES (
    #{reportNo}, #{reportName}, #{templateId}, #{reportType}, #{reportPeriod}, #{startDate}, #{endDate},
    #{reportFormat}, #{reportParams}, #{generateType}, #{reportStatus}, #{generateTime},
    #{description}, #{remark}, #{orgId}, CURRENT_TIMESTAMP, #{createUser}, CURRENT_TIMESTAMP, #{updateUser}
)

mapper.select:
SELECT COUNT(*) AS totalReports, COUNT(CASE WHEN REPORTSTATUS = 'COMPLETED' THEN 1 END) AS completedReports, COUNT(CASE WHEN REPORTSTATUS = 'GENERATING' THEN 1 END) AS generatingReports, COUNT(CASE WHEN REPORTSTATUS = 'FAILED' THEN 1 END) AS failedReports, COALESCE(SUM(DOWNLOADCOUNT), 0) AS totalDownloads, COALESCE(SUM(REPORTSIZE), 0) AS totalSize FROM TBL_FINANCING_REPORT_RECORDS
AND ORGID = #{params.orgId}
AND CREATETIME >= #{params.startDate}
AND CREATETIME <= #{params.endDate}

SELECT 
    REPORTTYPE AS reportType,
    COUNT(*) AS reportCount,
    COALESCE(SUM(DOWNLOADCOUNT), 0) AS downloadCount
FROM TBL_FINANCING_REPORT_RECORDS


        AND ORGID = #{params.orgId}


        AND CREATETIME >= #{params.startDate}


        AND CREATETIME <= #{params.endDate}


GROUP BY REPORTTYPE
ORDER BY reportCount DESC

SELECT COUNT(*) FROM TBL_FINANCING_REPORT_RECORDS 
WHERE REPORTNO = #{reportNo} AND ORGID = #{orgId}

    AND RECORDID != #{excludeId}

SELECT COUNT(*) FROM TBL_FINANCING_REPORT_TEMPLATES 
WHERE TEMPLATENO = #{templateNo} AND ORGID = #{orgId}

    AND TEMPLATEID != #{excludeId}
